import{_ as a,H as t,f as e,i as r}from"./chunks/framework.DLd0CbzH.js";const h=JSON.parse('{"title":"Резервное копирование и безопасность","description":"Автоматические GFS-бэкапы, ручной экспорт в ZIP/CSV, восстановление данных и защита от сбоев питания (WAL).","frontmatter":{"title":"Резервное копирование и безопасность","description":"Автоматические GFS-бэкапы, ручной экспорт в ZIP/CSV, восстановление данных и защита от сбоев питания (WAL).","order":17},"headers":[],"relativePath":"ru/docs/backups.md","filePath":"ru/docs/backups.md"}'),s={name:"ru/docs/backups.md"};function l(i,o,n,c,d,p){return t(),e("div",null,[...o[0]||(o[0]=[r('<div class="warning custom-block"><p class="custom-block-title">📌 Документация находится в разработке</p><p><strong>Уважаемые пользователи!</strong></p><p>Поскольку OmniCraft ERP сейчас находится в стадии активной бета-версии, регулярно дорабатывается и расширяется, справочные материалы также обновляются постепенно.</p><p>На данный момент воспринимайте документацию как ориентировочную — она является неполной, может временно не содержать описание некоторых функций или содержать неточности.</p></div><h1 id="🛡️-резервное-копирование-и-безопасность-данных" tabindex="-1">🛡️ Резервное копирование и безопасность данных <a class="header-anchor" href="#🛡️-резервное-копирование-и-безопасность-данных" aria-label="Permalink to &quot;🛡️ Резервное копирование и безопасность данных&quot;">​</a></h1><p>OmniCraft ERP — это локальное десктопное приложение. Мы принципиально не используем облачные серверы для хранения ваших финансовых операций, что гарантирует <strong>100% приватность</strong> и независимость от интернета.</p><p>Однако это означает, что физическая сохранность базы данных лежит на вашем компьютере. Чтобы защитить ваш бизнес от сбоев жесткого диска, случайных удалений или вирусов-шифровальщиков, в программу встроена многоуровневая система автоматического и ручного резервного копирования.</p><hr><h2 id="🔄-автоматические-теневые-копии-gfs-бэкапы" tabindex="-1">🔄 Автоматические теневые копии (GFS-бэкапы) <a class="header-anchor" href="#🔄-автоматические-теневые-копии-gfs-бэкапы" aria-label="Permalink to &quot;🔄 Автоматические теневые копии (GFS-бэкапы)&quot;">​</a></h2><p>Программа работает по профессиональной IT-стратегии <strong>GFS (Grandfather-Father-Son / Дед-Отец-Сын)</strong>. Фоновая система создает изолированные снимки базы данных без блокировки вашей работы и без торможения интерфейса.</p><h3 id="_1-при-запуске-программы-startup-backups" tabindex="-1">1. При запуске программы (Startup Backups) <a class="header-anchor" href="#_1-при-запуске-программы-startup-backups" aria-label="Permalink to &quot;1. При запуске программы (Startup Backups)&quot;">​</a></h3><p>Каждый раз, когда вы открываете OmniCraft ERP, система проверяет системное время и создает теневую копию, если наступил новый отчетный период:</p><ul><li>📅 <strong>Ежедневная копия</strong> (<code>auto_daily.db</code>) — обновляется раз в сутки.</li><li>🗓️ <strong>Еженедельная копия</strong> (<code>auto_weekly.db</code>) — обновляется раз в неделю.</li><li>🗓️ <strong>Ежемесячная копия</strong> (<code>auto_monthly.db</code>) — обновляется раз в месяц.</li><li>🗓️ <strong>Ежегодная копия</strong> (<code>auto_yearly.db</code>) — обновляется раз в год.</li></ul><h3 id="_2-при-закрытии-программы-close-backups" tabindex="-1">2. При закрытии программы (Close Backups) <a class="header-anchor" href="#_2-при-закрытии-программы-close-backups" aria-label="Permalink to &quot;2. При закрытии программы (Close Backups)&quot;">​</a></h3><p>Когда вы закрываете приложение, OmniCraft выполняет две важные вещи:</p><ol><li><strong>Оптимизация СУБД:</strong> Выполняются системные команды <code>PRAGMA optimize</code> и <code>VACUUM</code>, которые сжимают файл базы данных, убирают «пустоты» от удаленных записей и ускоряют будущие запросы.</li><li><strong>Ротационные копии:</strong> Создается цепочка из трех слотов (<code>auto_close_1.db</code>, <code>auto_close_2.db</code>, <code>auto_close_3.db</code>). При каждом закрытии новая копия сдвигает предыдущие на шаг назад. Это дает вам доступ к трем последним состояниям программы на момент её выключения.</li></ol><h3 id="_3-предохранительные-снимки-safety-nets" tabindex="-1">3. Предохранительные снимки (Safety Nets) <a class="header-anchor" href="#_3-предохранительные-снимки-safety-nets" aria-label="Permalink to &quot;3. Предохранительные снимки (Safety Nets)&quot;">​</a></h3><p>Перед выполнением любых необратимых или потенциально опасных операций программа <strong>автоматически</strong> делает теневой бэкап:</p><ul><li>Перед «Сбросом учета» (очисткой истории).</li><li>Перед «Полным сбросом» (Factory Reset).</li><li>Перед автоматической миграцией базы данных при обновлении версии программы.</li></ul><div class="tip custom-block"><p class="custom-block-title">Где хранятся автосохранения?</p><p>Все автоматические бэкапы лежат в защищенной системной папке приложения (<code>AppData/Roaming/OmniCraft/backups/</code> на Windows или <code>~/.config/OmniCraft/backups/</code> на macOS/Linux). Вы можете в любой момент скопировать их оттуда на флешку или в облако.</p></div><hr><h2 id="📦-ручнои-экспорт-данных-меню-«фаил»" tabindex="-1">📦 Ручной экспорт данных (Меню «Файл») <a class="header-anchor" href="#📦-ручнои-экспорт-данных-меню-«фаил»" aria-label="Permalink to &quot;📦 Ручной экспорт данных (Меню «Файл»)&quot;">​</a></h2><p>Для создания архивов, которые можно отправить по почте, положить в облачное хранилище или перенести на другой компьютер, используйте меню <strong>Файл ➔ Экспорт данных</strong>. Программа предлагает два формата:</p><h3 id="_1-бинарныи-бэкап-db" tabindex="-1">1. Бинарный бэкап (.db) <a class="header-anchor" href="#_1-бинарныи-бэкап-db" aria-label="Permalink to &quot;1. Бинарный бэкап (.db)&quot;">​</a></h3><p>Создает точную 1:1 копию вашего текущего файла базы данных.</p><ul><li><strong>Как это работает:</strong> Используется нативный SQLite API <code>.backup()</code>, который безопасно копирует данные «на лету», даже если в эту секунду программа проводит продажу.</li><li><strong>Для чего подходит:</strong> Для быстрого ежедневного сохранения на внешний диск или флешку.</li></ul><h3 id="_2-архив-таблиц-zip-с-csv" tabindex="-1">2. Архив таблиц (.zip с CSV) <a class="header-anchor" href="#_2-архив-таблиц-zip-с-csv" aria-label="Permalink to &quot;2. Архив таблиц (.zip с CSV)&quot;">​</a></h3><p>Сверхмощный экспорт, который выгружает <strong>абсолютно все</strong> системные таблицы (склад, чеки, рецепты, настройки) в виде отдельных текстовых файлов <code>.csv</code> и упаковывает их в единый <code>.zip</code> архив.</p><ul><li><strong>Для чего подходит:</strong> Это ваш «цифровой парашют». Если бинарный файл <code>.db</code> когда-либо получит микроповреждения из-за сбоя файловой системы и перестанет открываться, вы всегда сможете восстановить всю свою историю из CSV-таблиц. Кроме того, эти файлы можно открыть в Excel для внешнего аудита.</li></ul><div class="info custom-block"><p class="custom-block-title">Глобальный экспорт в PRO-режиме</p><p>Если вы используете PRO-версию с Мультипространствами, ручной экспорт упакует в единый ZIP-архив <strong>всю вашу экосистему</strong>: реестр <code>workspaces.json</code>, базу личных финансов (<code>personal_finance.db</code>) и все созданные вами бизнес-пространства.</p></div><hr><h2 id="⏳-восстановление-данных-импорт" tabindex="-1">⏳ Восстановление данных (Импорт) <a class="header-anchor" href="#⏳-восстановление-данных-импорт" aria-label="Permalink to &quot;⏳ Восстановление данных (Импорт)&quot;">​</a></h2><p>Если произошла авария, вы переносите программу на новый ПК или хотите «откатиться» на состояние вчерашнего дня, используйте меню <strong>Файл ➔ Импорт данных</strong>.</p><h3 id="восстановление-из-автосохранения-машина-времени" tabindex="-1">Восстановление из автосохранения (Машина времени) <a class="header-anchor" href="#восстановление-из-автосохранения-машина-времени" aria-label="Permalink to &quot;Восстановление из автосохранения (Машина времени)&quot;">​</a></h3><p>Выберите этот пункт, чтобы открыть список всех автоматических GFS-бэкапов. Программа покажет удобные карточки с датами и размером каждого снимка (например, <em>«Ежедневная копия (Вчера | 4.2 MB)»</em>).</p><ul><li>Выберите нужную точку во времени.</li><li>Подтвердите действие. Программа полностью перезапишет текущую базу выбранным снимком и <strong>автоматически перезагрузится</strong>.</li></ul><h3 id="восстановление-из-фаила-db-или-zip" tabindex="-1">Восстановление из файла (.db или .zip) <a class="header-anchor" href="#восстановление-из-фаила-db-или-zip" aria-label="Permalink to &quot;Восстановление из файла (.db или .zip)&quot;">​</a></h3><ul><li><strong>Из бинарного бэкапа (.db):</strong> Полностью заменяет текущую базу данных файлом, который вы укажете.</li><li><strong>Из CSV-архива (.zip):</strong> Программа распаковывает архив, очищает текущие таблицы и аккуратно, строка за строкой, восстанавливает данные. Встроенный строгий валидатор защищает от SQL-инъекций и случайной загрузки поврежденных файлов.</li></ul><div class="danger custom-block"><p class="custom-block-title">Внимание: Полная перезапись</p><p>Процесс импорта <strong>не объединяет</strong> данные, а полностью заменяет текущее состояние программы на то, что было в файле бэкапа. Все чеки, закупки и настройки, сделанные <em>после</em> создания загружаемого бэкапа, будут безвозвратно потеряны. Всегда делайте свежий экспорт перед тем, как накатывать старый бэкап!</p></div><hr><h2 id="⚙️-под-капотом-защита-от-сбоев-питания-wal" tabindex="-1">⚙️ Под капотом: Защита от сбоев питания (WAL) <a class="header-anchor" href="#⚙️-под-капотом-защита-от-сбоев-питания-wal" aria-label="Permalink to &quot;⚙️ Под капотом: Защита от сбоев питания (WAL)&quot;">​</a></h2><p>Помимо создания копий, сама архитектура базы данных OmniCraft ERP спроектирована для выживания в экстремальных условиях.</p><p>Программа использует режим журналирования <strong>WAL (Write-Ahead Logging)</strong>. В отличие от стандартных баз данных, которые могут необратимо повредиться, если во время записи чека в доме отключат электричество, WAL-режим работает иначе:</p><ol><li>Любое изменение сначала записывается в отдельный «журнал» (WAL-файл).</li><li>Только после успешной записи в журнал данные безопасно переносятся в основную базу.</li><li>Если свет моргнул или система зависла, при следующем запуске SQLite автоматически прочитает журнал и <strong>откатит</strong> незавершенную операцию.</li></ol><p>База данных останется структурно целостной, а ваша финансовая история не превратится в «кашу». Максимум, что вы потеряете — это последнюю секундную операцию, которую вы не успели завершить.</p><hr><h2 id="🧠-золотые-правила-безопасности" tabindex="-1">🧠 Золотые правила безопасности <a class="header-anchor" href="#🧠-золотые-правила-безопасности" aria-label="Permalink to &quot;🧠 Золотые правила безопасности&quot;">​</a></h2><p>Чтобы ваш бизнес был защищен на 100%, выработайте простые привычки:</p><ol><li><strong>Правило 3-2-1:</strong> Храните <strong>3</strong> копии данных, на <strong>2</strong> разных носителях (например, ПК и внешний HDD), и <strong>1</strong> копию в облаке (Яндекс.Диск, Google Drive).</li><li><strong>Еженедельный ручный экспорт:</strong> Раз в неделю заходите в <code>Файл ➔ Экспорт данных ➔ База таблицами (.zip)</code> и скидывайте архив себе в облако или на почту.</li><li><strong>Не игнорируйте обновления:</strong> При выходе новых версий OmniCraft ERP встроенная система миграции автоматически адаптирует вашу базу под новые функции, предварительно сделав защитный бэкап <code>auto_before_scale_migration.db</code>.</li></ol>',46)])])}const g=a(s,[["render",l]]);export{h as __pageData,g as default};
